// ---------- CONFIG ----------
const SPREADSHEET_ID = 'PASTE_YOUR_SHEET_ID_HERE';   // from the sheet URL: /spreadsheets/d/<ID>/edit
const SHEET_NAME = 'Invoices';
const EXEC_NAME = 'Marvin';
const PAYMENT_DETAILS = 'You can pay via bank transfer or the payment link on the invoice.';
const TZ = 'Asia/Manila';
const STAGES = [            // first matching stage (top to bottom) wins
  { key: 'final',    minDaysOverdue: 14 },
  { key: 'firm',     minDaysOverdue: 7 },
  { key: 'overdue',  minDaysOverdue: 1 },
  { key: 'upcoming', minDaysOverdue: -3 },   // 3 days before the due date
];
// ----------------------------
if (SPREADSHEET_ID.startsWith('PASTE_')) throw new Error('Set SPREADSHEET_ID in the Config node (see Setup Notes).');
return [{ json: { SPREADSHEET_ID, SHEET_NAME, EXEC_NAME, PAYMENT_DETAILS, TZ, STAGES } }];

const cfg = $('Config').first().json;
const rows = $input.first().json.values || [];
if (rows.length < 2) return [];
const head = rows[0].map(h => String(h).trim().toLowerCase());
const col = name => head.indexOf(name);
const need = ['invoice #', 'client', 'client email', 'amount', 'currency', 'due date', 'status', 'last reminder', 'reminder count'];
const missing = need.filter(n => col(n) < 0);
if (missing.length) throw new Error(`Invoices sheet is missing column(s): ${missing.join(', ')}. Use templates/invoices-template.csv.`);
const letter = i => String.fromCharCode(65 + i);

const today = $now.setZone(cfg.TZ).startOf('day');
const STAGE_RANK = { upcoming: 1, overdue: 2, firm: 3, final: 4 };
const out = [];
const totals = {};
let unpaidCount = 0, overdueCount = 0;

rows.slice(1).forEach((r, idx) => {
  const get = n => String(r[col(n)] ?? '').trim();
  const status = get('status').toLowerCase();
  if (!get('invoice #') || ['paid', 'void', 'cancelled'].includes(status)) return;
  const amount = parseFloat(get('amount').replace(/[^0-9.\-]/g, '')) || 0;
  const currency = get('currency') || 'USD';
  const dueRaw = get('due date');
  let due = DateTime.fromISO(dueRaw, { zone: cfg.TZ });
  if (!due.isValid) due = DateTime.fromFormat(dueRaw, 'M/d/yyyy', { zone: cfg.TZ });
  if (!due.isValid) return;
  unpaidCount++;
  totals[currency] = (totals[currency] || 0) + amount;
  const daysOverdue = Math.round(today.diff(due.startOf('day'), 'days').days);
  if (daysOverdue > 0) overdueCount++;

  const stage = cfg.STAGES.find(s => daysOverdue >= s.minDaysOverdue);
  if (!stage) return;
  const last = get('last reminder').split(' ')[0].toLowerCase();
  if (STAGE_RANK[last] >= STAGE_RANK[stage.key]) return;   // this stage (or a later one) already drafted
  const email = get('client email');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return;

  const inv = get('invoice #');
  const amt = `${currency} ${amount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  const dueTxt = due.toFormat('LLLL d, yyyy');
  const name = get('client').split(/\s+/)[0] || 'there';
  const copy = {
    upcoming: [`Upcoming: Invoice ${inv} due ${dueTxt}`, `Just a friendly heads-up that invoice ${inv} for ${amt} is due on ${dueTxt}.`],
    overdue:  [`Reminder: Invoice ${inv} is now due`, `I hope all is well. Invoice ${inv} for ${amt} was due on ${dueTxt} and still shows as open on our side. Could you let me know when we can expect payment?`],
    firm:     [`Second reminder: Invoice ${inv} is ${daysOverdue} days overdue`, `Following up on invoice ${inv} for ${amt}, which was due on ${dueTxt} and is now ${daysOverdue} days overdue. Please arrange payment at your earliest convenience, or let me know if there's an issue I can help resolve.`],
    final:    [`Final notice: Invoice ${inv} (${daysOverdue} days overdue)`, `This is a final reminder that invoice ${inv} for ${amt}, due on ${dueTxt}, remains unpaid (${daysOverdue} days overdue). Please settle it this week or reply so we can agree on a payment date.`],
  }[stage.key];
  const body = [`Hi ${name},`, '', copy[1], '', cfg.PAYMENT_DETAILS, '', 'If you have already sent payment, thank you - please ignore this note.', '', 'Best regards,', cfg.EXEC_NAME].join('\r\n');
  const b64 = s => Buffer.from(s, 'utf8').toString('base64');
  const mime = [`To: ${email}`, `Subject: =?UTF-8?B?${b64(copy[0])}?=`, 'MIME-Version: 1.0', 'Content-Type: text/plain; charset="UTF-8"', 'Content-Transfer-Encoding: base64'].join('\r\n') + '\r\n\r\n' + b64(body);
  const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

  const rowNum = idx + 2;
  const count = (parseInt(get('reminder count'), 10) || 0) + 1;
  out.push({ json: {
    invoice: inv, client: get('client'), amount: amt, stage: stage.key, daysOverdue,
    draftBody: { message: { raw } },
    updateRange: `${cfg.SHEET_NAME}!${letter(col('last reminder'))}${rowNum}:${letter(col('reminder count'))}${rowNum}`,
    updateBody: { values: [col('reminder count') === col('last reminder') + 1
      ? [`${stage.key} ${today.toISODate()}`, count]
      : [`${stage.key} ${today.toISODate()}`]] },
    countRange: `${cfg.SHEET_NAME}!${letter(col('reminder count'))}${rowNum}`, count,
  } });
});

const state = $getWorkflowStaticData('global');
state.summary = { totals, unpaidCount, overdueCount, at: $now.toISO() };
if (!out.length) return [{ json: { none: true } }];
return out;

const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global').summary || { totals: {}, unpaidCount: 0, overdueCount: 0 };
let drafted = [];
try { drafted = $('Plan Reminders').all().map(i => i.json).filter(j => !j.none); } catch (e) {}
const isMonday = $now.setZone(cfg.TZ).weekday === 1;
if (!drafted.length && !isMonday) return [];

const totals = Object.entries(s.totals).map(([c, v]) => `${c} ${v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`).join(' / ') || 'nothing';
const icon = { upcoming: ':calendar:', overdue: ':warning:', firm: ':exclamation:', final: ':rotating_light:' };
const lines = drafted.map(d => `${icon[d.stage] || ''} ${d.invoice} - ${d.client} - ${d.amount} (${d.stage}${d.daysOverdue > 0 ? `, ${d.daysOverdue}d overdue` : ''})`);
const text = [`*Invoices* - ${s.unpaidCount} unpaid (${s.overdueCount} overdue), outstanding: ${totals}`,
  drafted.length ? `\n*Reminder drafts ready in Gmail (${drafted.length}):*\n${lines.join('\n')}` : '\n_No reminders due today._'].join('');
return [{ json: { text } }];
